-- R-058/R-097/R-098/R-099. Opt-in real local Qwen/E5 candidates, reviewed adoption only.
ALTER TABLE live_answer_configurations ADD COLUMN invalidated_at text;
ALTER TABLE live_answer_configurations ADD COLUMN invalidation_reason text;
ALTER TABLE live_answer_jobs ADD COLUMN invalidated_at text;
ALTER TABLE live_answer_jobs ADD COLUMN invalidation_reason text;
ALTER TABLE live_answer_origins ADD COLUMN input_hash text NOT NULL;
ALTER TABLE live_answer_origins ADD COLUMN result_hash text NOT NULL;
ALTER TABLE live_answer_origins ADD COLUMN session_version bigint NOT NULL;
ALTER TABLE live_answer_origins ADD COLUMN question_version bigint NOT NULL;
ALTER TABLE live_answer_origins ADD COLUMN epoch bigint NOT NULL;
CREATE TABLE _dg_native_live_answer_config_versions(session_id text NOT NULL REFERENCES live_sessions(id),generation bigint NOT NULL,snapshot text NOT NULL,snapshot_hash text NOT NULL CHECK(snapshot_hash=encode(sha256(convert_to(snapshot,'UTF8')),'hex')),created_at text NOT NULL,PRIMARY KEY(session_id,generation));
CREATE TABLE _dg_native_live_answer_inputs(job_id text PRIMARY KEY REFERENCES live_answer_jobs(id),snapshot text NOT NULL,input_hash text NOT NULL CHECK(input_hash=encode(sha256(convert_to(snapshot,'UTF8')),'hex')),created_at text NOT NULL);
CREATE TABLE _dg_native_live_answer_outputs(job_id text PRIMARY KEY REFERENCES live_answer_jobs(id),lease_token text NOT NULL,result text NOT NULL,evidence text NOT NULL,result_hash text NOT NULL,created_at text NOT NULL);
CREATE TRIGGER native_live_answer_config_immutable BEFORE UPDATE OR DELETE ON _dg_native_live_answer_config_versions FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
CREATE TRIGGER native_live_answer_input_immutable BEFORE UPDATE OR DELETE ON _dg_native_live_answer_inputs FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
CREATE TRIGGER native_live_answer_output_immutable BEFORE UPDATE OR DELETE ON _dg_native_live_answer_outputs FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
ALTER TABLE native_model_leases DROP CONSTRAINT native_content_cpu_shape;
ALTER TABLE native_model_leases ADD CONSTRAINT native_live_answer_cpu_shape CHECK(resource='qwen3-4b-cpu' AND job_kind IN('presentation-answer','content-writing','live-answer') AND char_length(token)=36);
ALTER TABLE live_answer_configurations ADD CONSTRAINT native_live_answer_config_shape CHECK(environment='mock' AND app_env IN('development','sandbox') AND enabled IN(0,1) AND auto_draft IN(0,1) AND language IN('zh-CN','en-US') AND generation BETWEEN 1 AND 200 AND version>0 AND(enabled=1 OR auto_draft=0) AND(enabled=0 OR engine IS NOT NULL AND engine::jsonb->>'policy'='live-public-grounded-v1' AND engine::jsonb->>'queryPolicy'='literal-query-span-v1'));
ALTER TABLE live_answer_jobs ADD CONSTRAINT native_live_answer_job_shape CHECK(environment='mock' AND app_env IN('development','sandbox') AND status IN('queued','processing','succeeded','failed','cancelled','stale') AND version>0 AND control_version BETWEEN 1 AND version AND attempts BETWEEN 0 AND 3 AND progress BETWEEN 0 AND 1 AND controller_version>0 AND question_version>0 AND configuration_generation>0 AND input_hash ~ '^[a-f0-9]{64}$' AND jsonb_typeof(request::jsonb->'sources')='array' AND jsonb_array_length(request::jsonb->'sources') BETWEEN 1 AND 512 AND configuration::jsonb->'engine'->>'policy'='live-public-grounded-v1' AND configuration::jsonb->'engine'->>'queryPolicy'='literal-query-span-v1' AND((lease_token IS NULL)=(lease_until IS NULL)) AND(status<>'succeeded' OR result IS NOT NULL AND evidence IS NOT NULL AND result_hash IS NOT NULL));
ALTER TABLE live_audience_events DROP CONSTRAINT native_live_audience_shape;
ALTER TABLE live_audience_events ADD CONSTRAINT native_live_audience_shape CHECK(version>0 AND priority BETWEEN 0 AND 2 AND status IN('received','queued','rejected','authorized_simulation','ready','playing','answered','cancelled') AND kind IN('comment','question','join_request') AND media_opt_in IN('none','audio','video') AND(answer_kind IS NULL OR answer_kind IN('manual','product','knowledge','local_model')) AND((answer_kind='knowledge' AND jsonb_typeof(citations::jsonb)='array' AND jsonb_array_length(citations::jsonb)<=5) OR(answer_kind='local_model' AND jsonb_typeof(citations::jsonb)='array' AND jsonb_array_length(citations::jsonb)<=8) OR(answer_kind IS DISTINCT FROM 'knowledge' AND answer_kind IS DISTINCT FROM 'local_model' AND citations='[]')) AND input_hash ~ '^[a-f0-9]{64}$' AND participant_hash ~ '^[a-f0-9]{64}$');

-- Only fixed schema keys are canonicalised here; arbitrary user object keys are never hashed as input.
CREATE FUNCTION dg_native_live_answer_canonical(v jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path FROM CURRENT AS $dg$
DECLARE result text;
BEGIN
 IF jsonb_typeof(v)='object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||dg_native_live_answer_canonical(value),',' ORDER BY key COLLATE "C"),'')||'}' INTO result FROM jsonb_each(v);RETURN result;
 ELSIF jsonb_typeof(v)='array' THEN SELECT '['||coalesce(string_agg(dg_native_live_answer_canonical(value),',' ORDER BY ordinal),'')||']' INTO result FROM jsonb_array_elements(v) WITH ORDINALITY a(value,ordinal);RETURN result;END IF;RETURN v::text;
END $dg$;
-- Match JS's 600 UTF-16-unit chunks with 50 Unicode-code-point overlap, never splitting a surrogate.
CREATE FUNCTION dg_native_live_answer_chunks(raw text) RETURNS text[] LANGUAGE plpgsql IMMUTABLE STRICT SET search_path FROM CURRENT AS $dg$
DECLARE value text:=btrim(replace(replace(raw,E'\r\n',E'\n'),E'\r',E'\n'),E' \t\n\r'||chr(11)||chr(12)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279));part text:='';c text;units integer:=0;size integer;result text[]:=ARRAY[]::text[];
BEGIN
 FOR i IN 1..char_length(value) LOOP c:=substr(value,i,1);size:=CASE WHEN ascii(c)>65535 THEN 2 ELSE 1 END;
  IF units+size>600 THEN result:=array_append(result,part);part:=right(part,50);SELECT coalesce(sum(CASE WHEN ascii(ch)>65535 THEN 2 ELSE 1 END),0) INTO units FROM regexp_split_to_table(part,'') ch;END IF;part:=part||c;units:=units+size;
 END LOOP;IF part<>'' THEN result:=array_append(result,part);END IF;RETURN result;
END $dg$;
CREATE FUNCTION dg_native_live_answer_member(actor text,tenant text,workspace text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT EXISTS(SELECT 1 FROM memberships m WHERE m.user_id=actor AND m.tenant_id=tenant AND m.role IN('admin','editor') AND m.workspace_ids::jsonb ? workspace);
$dg$;
CREATE FUNCTION dg_native_live_answer_source_valid(target text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j live_answer_jobs%ROWTYPE;s live_sessions%ROWTYPE;q live_audience_events%ROWTYPE;v jsonb;c jsonb;p jsonb;published record;parts text[];cache jsonb:='{}'::jsonb;key text;total integer:=0;cfg jsonb;
BEGIN
 SELECT * INTO j FROM live_answer_jobs WHERE id=target;IF NOT FOUND OR j.invalidated_at IS NOT NULL OR j.withdrawn_at IS NOT NULL OR NOT dg_native_live_answer_member(j.actor_id,j.tenant_id,j.workspace_id) THEN RETURN false;END IF;
 SELECT * INTO s FROM live_sessions WHERE id=j.session_id;SELECT * INTO q FROM live_audience_events WHERE id=j.question_id;SELECT snapshot::jsonb INTO cfg FROM _dg_native_live_answer_config_versions WHERE session_id=j.session_id AND generation=j.configuration_generation;
 IF s.id IS NULL OR s.invalidated_at IS NOT NULL OR s.tenant_id<>j.tenant_id OR s.workspace_id<>j.workspace_id OR s.environment<>j.environment OR s.app_env<>j.app_env OR s.snapshot_hash<>j.session_hash OR q.session_id IS DISTINCT FROM s.id OR q.text IS DISTINCT FROM j.request::jsonb->>'question' OR cfg IS NULL OR cfg->'engine' IS DISTINCT FROM j.configuration::jsonb->'engine' OR cfg->>'language' IS DISTINCT FROM j.configuration::jsonb->>'language' OR NOT dg_native_live_answer_member(cfg->>'actorId',j.tenant_id,j.workspace_id) OR NOT dg_native_live_scene_valid(s.id) OR NOT EXISTS(SELECT 1 FROM _dg_native_live_answer_inputs i WHERE i.job_id=j.id AND i.input_hash=j.input_hash) THEN RETURN false;END IF;
 IF j.request::jsonb->>'language' IS DISTINCT FROM j.configuration::jsonb->>'language' OR char_length(j.request::jsonb->>'question') NOT BETWEEN 1 AND 1000 OR(SELECT count(DISTINCT item->>'id') FROM jsonb_array_elements(j.request::jsonb->'sources') item)<>jsonb_array_length(j.request::jsonb->'sources') THEN RETURN false;END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(j.request::jsonb->'sources') LOOP
  IF v->>'kind'='knowledge' THEN
   SELECT c.id AS collection_id,c.tenant_id,c.workspace_id,c.environment,c.app_env,c.audience,c.scenes,d.id AS document_id,d.tenant_id AS document_tenant,d.workspace_id AS document_workspace,d.published_version_id,k.* INTO published FROM knowledge_collections c JOIN knowledge_documents d ON d.collection_id=c.id JOIN knowledge_versions k ON k.id=d.published_version_id AND k.document_id=d.id WHERE c.id=v->>'collectionId' AND d.id=v->>'documentId' AND k.id=v->>'versionId';
   IF NOT FOUND OR published.tenant_id<>j.tenant_id OR published.document_tenant<>j.tenant_id OR published.workspace_id<>j.workspace_id OR published.document_workspace<>j.workspace_id OR published.environment<>j.environment OR published.app_env<>j.app_env OR published.audience<>'public' OR NOT(published.scenes::jsonb ? 'live') OR NOT(coalesce(s.snapshot::jsonb->'scene'->'app'->'collectionIds','[]'::jsonb) ? published.collection_id) OR published.status<>'published' OR published.content_hash<>v->>'contentHash' OR published.content_hash<>encode(sha256(convert_to(published.content,'UTF8')),'hex') OR published.ordinal<>(v->>'version')::bigint OR published.title<>v->>'title' OR published.source_label<>v->>'sourceLabel' OR to_jsonb(published.source_url) IS DISTINCT FROM nullif(v->'sourceUrl','null'::jsonb) THEN RETURN false;END IF;
   key:='k:'||published.id;IF NOT(cache ? key) THEN cache:=jsonb_set(cache,ARRAY[key],to_jsonb(dg_native_live_answer_chunks(published.content)));END IF;
   IF(SELECT count(*) FROM jsonb_array_elements(j.request::jsonb->'sources') a WHERE a->>'kind'='knowledge' AND a->>'versionId'=v->>'versionId')<>jsonb_array_length(cache->key) THEN RETURN false;END IF;
  ELSIF v->>'kind'='product' THEN
   SELECT value INTO p FROM jsonb_array_elements(s.snapshot::jsonb->'definition'->'products') WHERE value->>'id'=v->>'productId';
   IF p IS NULL OR p->>'expiresAt'<=dg_utc_now() OR p->>'expiresAt'<>v->>'expiresAt' OR encode(sha256(convert_to(dg_native_live_answer_canonical(p),'UTF8')),'hex')<>v->>'productHash' OR p->>'name'<>v->>'title' OR p->>'sourceLabel'<>v->>'sourceLabel' OR p->'sourceUrl' IS DISTINCT FROM v->'sourceUrl' THEN RETURN false;END IF;
   key:='p:'||(p->>'id');IF NOT(cache ? key) THEN cache:=jsonb_set(cache,ARRAY[key],to_jsonb(dg_native_live_answer_chunks('商品名称：'||(p->>'name')||CASE WHEN coalesce(p->>'priceLabel','')<>'' THEN E'\n资料标价：'||(p->>'priceLabel') ELSE '' END||E'\n说明：'||(p->>'description'))));END IF;
   IF(SELECT count(*) FROM jsonb_array_elements(j.request::jsonb->'sources') a WHERE a->>'kind'='product' AND a->>'productId'=v->>'productId')<>jsonb_array_length(cache->key) THEN RETURN false;END IF;
  ELSE RETURN false;END IF;
  IF(v->>'part')::integer<0 OR v->>'text' IS DISTINCT FROM cache->key->>((v->>'part')::integer) OR v->>'id' !~ '^s[0-9]+c[0-9]+$' THEN RETURN false;END IF;
  SELECT coalesce(sum(CASE WHEN ascii(ch)>65535 THEN 2 ELSE 1 END),0) INTO total FROM regexp_split_to_table(v->>'text','') ch;IF total NOT BETWEEN 1 AND 600 THEN RETURN false;END IF;
 END LOOP;
 SELECT coalesce(sum(char_length(item->>'text')+(SELECT count(*) FROM regexp_split_to_table(item->>'text','') ch WHERE ascii(ch)>65535)),0) INTO total FROM jsonb_array_elements(j.request::jsonb->'sources') item;RETURN total<=180000;
EXCEPTION WHEN data_exception THEN RETURN false;
END $dg$;
CREATE FUNCTION dg_native_live_answer_result_valid(target text,result_text text,evidence_text text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j live_answer_jobs%ROWTYPE;r jsonb:=result_text::jsonb;e jsonb:=evidence_text::jsonb;c jsonb;s jsonb;
BEGIN
 IF NOT coalesce(jsonb_typeof(r)='object' AND jsonb_typeof(r->'supported')='boolean' AND jsonb_typeof(r->'answer')='string' AND jsonb_typeof(r->'citations')='array' AND jsonb_typeof(e)='object' AND jsonb_typeof(e->'engine')='object' AND jsonb_typeof(e->'retrievedSourceIds')='array' AND jsonb_typeof(e->'effectiveQuestion')='string' AND e->>'inputSHA256' ~ '^[a-f0-9]{64}$' AND e->>'promptSHA256' ~ '^[a-f0-9]{64}$' AND e->>'rawOutputSHA256' ~ '^[a-f0-9]{64}$' AND e->>'queryPromptSHA256' ~ '^[a-f0-9]{64}$' AND e->>'queryRawOutputSHA256' ~ '^[a-f0-9]{64}$' AND(e->>'promptTokens')::bigint>=0 AND(e->>'queryPromptTokens')::bigint>=0 AND(e->>'elapsedMs')::double precision>=0 AND(e->>'retrievalInferences')::bigint>0 AND jsonb_typeof(e->'compiledWorkerEntry')='boolean' AND e->>'offlineCpu'='true',false) THEN RETURN false;END IF;
 SELECT * INTO j FROM live_answer_jobs WHERE id=target;IF NOT FOUND OR e->'engine' IS DISTINCT FROM j.configuration::jsonb->'engine' OR e->>'inputSHA256'<>encode(sha256(convert_to(dg_native_live_answer_canonical(j.request::jsonb),'UTF8')),'hex') OR char_length(e->>'effectiveQuestion') NOT BETWEEN 1 AND 1000 OR strpos(j.request::jsonb->>'question',e->>'effectiveQuestion')=0 OR char_length(r->>'answer') NOT BETWEEN 1 AND 1200 OR jsonb_typeof(r->'citations')<>'array' OR jsonb_array_length(r->'citations')>8 OR jsonb_typeof(e->'retrievedSourceIds')<>'array' OR jsonb_array_length(e->'retrievedSourceIds') NOT BETWEEN 1 AND 8 OR(r->>'supported')::boolean<>(jsonb_array_length(r->'citations')>0) OR e->>'offlineCpu'<>'true' THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(e->'retrievedSourceIds') id WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(j.request::jsonb->'sources') item WHERE item->>'id'=id)) OR(SELECT count(DISTINCT id) FROM jsonb_array_elements_text(e->'retrievedSourceIds') id)<>jsonb_array_length(e->'retrievedSourceIds') THEN RETURN false;END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(r->'citations') LOOP SELECT value INTO s FROM jsonb_array_elements(j.request::jsonb->'sources') WHERE value->>'id'=c->>'sourceId';IF s IS NULL OR s->>'kind'<>c->>'kind' OR s->>'title'<>c->>'title' OR s->>'sourceLabel'<>c->>'sourceLabel' OR s->'sourceUrl' IS DISTINCT FROM c->'sourceUrl' OR char_length(btrim(c->>'quote'))=0 OR strpos(s->>'text',c->>'quote')=0 OR NOT(e->'retrievedSourceIds' ? (c->>'sourceId')) THEN RETURN false;END IF;END LOOP;RETURN true;
EXCEPTION WHEN data_exception THEN RETURN false;
END $dg$;
CREATE FUNCTION dg_native_live_answer_valid(target text,expected_token text,completed boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j live_answer_jobs%ROWTYPE;s live_sessions%ROWTYPE;q live_audience_events%ROWTYPE;c live_answer_configurations%ROWTYPE;
BEGIN
 SELECT * INTO j FROM live_answer_jobs WHERE id=target;IF NOT FOUND OR NOT dg_native_live_answer_source_valid(target) THEN RETURN false;END IF;
 IF completed THEN RETURN j.status='succeeded' AND EXISTS(SELECT 1 FROM _dg_native_live_answer_outputs o WHERE o.job_id=j.id AND o.result=j.result AND o.evidence=j.evidence AND o.result_hash=j.result_hash) AND dg_native_live_answer_result_valid(j.id,j.result,j.evidence);END IF;
 SELECT * INTO s FROM live_sessions WHERE id=j.session_id;SELECT * INTO q FROM live_audience_events WHERE id=j.question_id;SELECT * INTO c FROM live_answer_configurations WHERE session_id=s.id;
 RETURN coalesce(j.status='processing' AND j.lease_token=expected_token AND j.lease_until>dg_utc_now() AND EXISTS(SELECT 1 FROM native_model_leases l WHERE l.resource='qwen3-4b-cpu' AND l.job_kind='live-answer' AND l.job_id=j.id AND l.token=expected_token AND l.lease_until>dg_utc_now()) AND s.status IN('live','preview') AND s.version=j.controller_version AND s.state::jsonb->>'manual'='false' AND s.state::jsonb->>'interactionsPaused'='false' AND s.state::jsonb->>'answerId' IS NULL AND s.snapshot::jsonb->'definition'->>'questionsEnabled'='true' AND q.status='queued' AND q.kind='question' AND q.version=j.question_version AND c.enabled=1 AND c.invalidated_at IS NULL AND c.generation=j.configuration_generation AND c.engine::jsonb=j.configuration::jsonb->'engine' AND c.language=j.configuration::jsonb->>'language' AND dg_native_live_answer_member(c.actor_id,j.tenant_id,j.workspace_id),false);
END $dg$;
CREATE FUNCTION dg_native_live_answer_config_guard() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$
DECLARE s live_sessions%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Live answer configuration history is preserved';END IF;SELECT * INTO s FROM live_sessions WHERE id=NEW.session_id;
 IF s.id IS NULL OR NEW.tenant_id<>s.tenant_id OR NEW.workspace_id<>s.workspace_id OR NEW.environment<>s.environment OR NEW.app_env<>s.app_env THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Live answer configuration must match the session scope';END IF;
 IF TG_OP='UPDATE' AND(to_jsonb(NEW)-ARRAY['actor_id','enabled','auto_draft','language','engine','generation','version','invalidated_at','invalidation_reason','updated_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['actor_id','enabled','auto_draft','language','engine','generation','version','invalidated_at','invalidation_reason','updated_at'] OR NEW.version<>OLD.version+1 OR NOT(NEW.generation=OLD.generation+1 OR NEW.generation=OLD.generation AND OLD.invalidated_at IS NULL AND NEW.invalidated_at IS NOT NULL AND(NEW.actor_id,NEW.enabled,NEW.auto_draft,NEW.language,NEW.engine) IS NOT DISTINCT FROM(OLD.actor_id,OLD.enabled,OLD.auto_draft,OLD.language,OLD.engine))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Configuration updates advance a generation or permanently invalidate its authorisation';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_live_answer_config_guard BEFORE INSERT OR UPDATE OR DELETE ON live_answer_configurations FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_config_guard();
CREATE FUNCTION dg_native_live_answer_job_guard() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$
DECLARE s live_sessions%ROWTYPE;q live_audience_events%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Live model task history is preserved';END IF;SELECT * INTO s FROM live_sessions WHERE id=NEW.session_id;SELECT * INTO q FROM live_audience_events WHERE id=NEW.question_id;
 IF s.id IS NULL OR q.session_id IS DISTINCT FROM s.id OR NEW.tenant_id<>s.tenant_id OR NEW.workspace_id<>s.workspace_id OR NEW.environment<>s.environment OR NEW.app_env<>s.app_env OR NEW.session_hash<>s.snapshot_hash OR NEW.request::jsonb->>'question' IS DISTINCT FROM q.text THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Live model input must match its actual question and session';END IF;
 IF TG_OP='INSERT' THEN IF NEW.status<>'queued' OR NEW.version<>1 OR NEW.attempts<>0 OR NEW.lease_token IS NOT NULL OR NEW.result IS NOT NULL OR NEW.evidence IS NOT NULL OR NEW.result_hash IS NOT NULL OR NEW.withdrawn_at IS NOT NULL OR NEW.invalidated_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Live model tasks start queued with no fabricated result';END IF;
 ELSE IF to_jsonb(NEW)-ARRAY['status','version','control_version','attempts','progress','lease_token','lease_until','result','evidence','result_hash','withdrawn_at','invalidated_at','invalidation_reason','error_code','error_message','updated_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['status','version','control_version','attempts','progress','lease_token','lease_until','result','evidence','result_hash','withdrawn_at','invalidated_at','invalidation_reason','error_code','error_message','updated_at'] OR NEW.version NOT BETWEEN OLD.version AND OLD.version+1 OR NEW.attempts NOT BETWEEN OLD.attempts AND OLD.attempts+1 OR(OLD.invalidated_at IS NOT NULL AND NEW.invalidated_at IS DISTINCT FROM OLD.invalidated_at) OR(OLD.withdrawn_at IS NOT NULL AND NEW.withdrawn_at IS DISTINCT FROM OLD.withdrawn_at) OR(OLD.result_hash IS NOT NULL AND(NEW.result,NEW.evidence,NEW.result_hash) IS DISTINCT FROM(OLD.result,OLD.evidence,OLD.result_hash)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Live model identity, result and attempt history cannot be overwritten';END IF;END IF;
 IF NEW.status='succeeded' AND NOT EXISTS(SELECT 1 FROM _dg_native_live_answer_outputs o WHERE o.job_id=NEW.id AND o.result=NEW.result AND o.evidence=NEW.evidence AND o.result_hash=NEW.result_hash) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Completed live answer requires its immutable worker receipt';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_live_answer_job_guard BEFORE INSERT OR UPDATE OR DELETE ON live_answer_jobs FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_job_guard();
CREATE FUNCTION dg_native_live_answer_input_guard() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$
DECLARE expected jsonb;
BEGIN
 IF TG_TABLE_NAME='_dg_native_live_answer_config_versions' THEN SELECT jsonb_build_object('actorId',actor_id,'enabled',enabled=1,'autoDraft',auto_draft=1,'language',language,'engine',engine::jsonb) INTO expected FROM live_answer_configurations WHERE session_id=NEW.session_id AND generation=NEW.generation;IF expected IS DISTINCT FROM NEW.snapshot::jsonb THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Configuration history must match its original generation';END IF;
 ELSE SELECT jsonb_build_object('sessionHash',session_hash,'request',request::jsonb,'configuration',configuration::jsonb,'controllerVersion',controller_version,'questionVersion',question_version,'configurationGeneration',configuration_generation,'actorId',actor_id) INTO expected FROM live_answer_jobs WHERE id=NEW.job_id AND input_hash=NEW.input_hash;IF expected IS NULL OR expected IS DISTINCT FROM NEW.snapshot::jsonb THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Live model ledger must match its actual fixed input';END IF;END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_live_answer_config_input_guard BEFORE INSERT ON _dg_native_live_answer_config_versions FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_input_guard();
CREATE TRIGGER native_live_answer_input_guard BEFORE INSERT ON _dg_native_live_answer_inputs FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_input_guard();

CREATE FUNCTION dg_native_live_answer_claim() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE r live_answer_jobs%ROWTYPE;env text;new_token text:=gen_random_uuid()::text;until_at text:=to_char((clock_timestamp()+interval '30 seconds') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('native-local-qwen-cpu',0));SELECT app_env INTO env FROM _dg_native_runtime_control WHERE id=1;
 IF EXISTS(SELECT 1 FROM native_model_leases WHERE resource='qwen3-4b-cpu' AND lease_until>dg_utc_now()) THEN RETURN NULL;END IF;DELETE FROM native_model_leases WHERE resource='qwen3-4b-cpu' AND lease_until<=dg_utc_now();
 UPDATE live_answer_jobs SET status='failed',version=version+1,lease_token=NULL,lease_until=NULL,error_code='LIVE_ANSWER_INTERRUPTED',error_message='原任务中断且三次恢复已用完，请转人工或按当前问题重新准备。',updated_at=dg_utc_now() WHERE app_env=env AND status='processing' AND lease_until<=dg_utc_now() AND attempts>=3;
 SELECT * INTO r FROM live_answer_jobs WHERE environment='mock' AND app_env=env AND invalidated_at IS NULL AND withdrawn_at IS NULL AND attempts<3 AND(status='queued' OR status='processing' AND lease_until<=dg_utc_now()) ORDER BY created_at,id LIMIT 1 FOR UPDATE SKIP LOCKED;IF NOT FOUND THEN RETURN NULL;END IF;
 UPDATE live_answer_jobs SET status='processing',attempts=attempts+1,version=version+1,lease_token=new_token,lease_until=until_at,error_code=NULL,error_message=NULL,updated_at=dg_utc_now() WHERE id=r.id RETURNING * INTO r;INSERT INTO native_model_leases VALUES('qwen3-4b-cpu','live-answer',r.id,new_token,until_at);RETURN to_jsonb(r);
END $dg$;
CREATE FUNCTION dg_native_live_answer_hold(target text,expected_token text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('native-local-qwen-cpu',0));UPDATE native_model_leases SET lease_until=to_char((clock_timestamp()+interval '30 seconds') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') WHERE resource='qwen3-4b-cpu' AND job_kind='live-answer' AND job_id=target AND token=expected_token AND lease_until>dg_utc_now();RETURN FOUND;END $dg$;
CREATE FUNCTION dg_native_live_answer_renew(target text,expected_token text,fraction double precision) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF fraction IS NULL OR fraction<0 OR fraction>.96 OR NOT dg_native_live_answer_valid(target,expected_token,false) THEN RETURN false;END IF;UPDATE live_answer_jobs SET lease_until=to_char((clock_timestamp()+interval '30 seconds') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),progress=greatest(progress,fraction) WHERE id=target AND lease_token=expected_token;RETURN FOUND;END $dg$;
CREATE FUNCTION dg_native_live_answer_release(target text,expected_token text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('native-local-qwen-cpu',0));DELETE FROM native_model_leases WHERE resource='qwen3-4b-cpu' AND job_kind='live-answer' AND job_id=target AND token=expected_token;RETURN FOUND;END $dg$;
CREATE FUNCTION dg_native_live_answer_fail(target text,expected_token text,code text,message text,interrupted boolean,stale boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN
 IF char_length(code)>100 OR char_length(message)>1000 OR NOT EXISTS(SELECT 1 FROM native_model_leases WHERE resource='qwen3-4b-cpu' AND job_kind='live-answer' AND job_id=target AND token=expected_token AND lease_until>dg_utc_now()) THEN RETURN false;END IF;
 UPDATE live_answer_jobs SET status=CASE WHEN stale THEN 'stale' WHEN interrupted AND attempts<3 THEN 'queued' ELSE 'failed' END,version=version+1,lease_token=NULL,lease_until=NULL,error_code=code,error_message=message,updated_at=dg_utc_now() WHERE id=target AND status='processing' AND lease_token=expected_token;RETURN FOUND;
END $dg$;
CREATE FUNCTION dg_native_commit_live_answer(target text,expected_token text,input_digest text,result_text text,evidence_text text,result_digest text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN
 IF NOT dg_native_live_answer_valid(target,expected_token,false) OR NOT dg_native_live_answer_result_valid(target,result_text,evidence_text) OR input_digest IS DISTINCT FROM(SELECT input_hash FROM live_answer_jobs WHERE id=target) OR result_digest<>encode(sha256(convert_to(dg_native_live_answer_canonical(result_text::jsonb),'UTF8')),'hex') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Actual live answer completion must match the live lease, fixed engine and grounded input';END IF;
 INSERT INTO _dg_native_live_answer_outputs VALUES(target,expected_token,result_text,evidence_text,result_digest,dg_utc_now());UPDATE live_answer_jobs SET status='succeeded',version=version+1,progress=1,result=result_text,evidence=evidence_text,result_hash=result_digest,lease_token=NULL,lease_until=NULL,error_code=NULL,error_message=NULL,updated_at=dg_utc_now() WHERE id=target;RETURN true;
END $dg$;
CREATE FUNCTION dg_native_live_model_answer_valid(target text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE o live_answer_origins%ROWTYPE;j live_answer_jobs%ROWTYPE;q live_audience_events%ROWTYPE;citations jsonb;product_ids text[];
BEGIN
 SELECT * INTO o FROM live_answer_origins WHERE question_id=target;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO j FROM live_answer_jobs WHERE id=o.job_id;SELECT * INTO q FROM live_audience_events WHERE id=target;
 IF NOT dg_native_live_answer_valid(j.id,NULL,true) OR NOT dg_native_live_answer_member(o.accepted_by,j.tenant_id,j.workspace_id) OR q.answer_kind<>'local_model' OR q.session_id<>j.session_id OR q.id<>j.question_id OR q.answer IS DISTINCT FROM j.result::jsonb->>'answer' OR o.input_hash<>j.input_hash OR o.result_hash<>j.result_hash OR q.prepared_epoch<>o.epoch THEN RETURN false;END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('collectionId',s->>'collectionId','documentId',s->>'documentId','versionId',s->>'versionId','version',(s->>'version')::bigint,'title',s->>'title','sourceLabel',s->>'sourceLabel','sourceUrl',s->'sourceUrl','snippet',c->>'quote') ORDER BY n),'[]'::jsonb) INTO citations FROM jsonb_array_elements(j.result::jsonb->'citations') WITH ORDINALITY a(c,n) JOIN LATERAL(SELECT value AS s FROM jsonb_array_elements(j.request::jsonb->'sources') WHERE value->>'id'=c->>'sourceId' AND value->>'kind'='knowledge') b ON true;
 SELECT array_agg(DISTINCT s->>'productId') INTO product_ids FROM jsonb_array_elements(j.result::jsonb->'citations') c JOIN LATERAL(SELECT value AS s FROM jsonb_array_elements(j.request::jsonb->'sources') WHERE value->>'id'=c->>'sourceId' AND value->>'kind'='product') b ON true;
 RETURN citations=q.citations::jsonb AND q.product_id IS NOT DISTINCT FROM CASE WHEN cardinality(product_ids)=1 THEN product_ids[1] ELSE NULL END;
EXCEPTION WHEN data_exception THEN RETURN false;
END $dg$;
CREATE FUNCTION dg_native_live_answer_origin_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j live_answer_jobs%ROWTYPE;q live_audience_events%ROWTYPE;s live_sessions%ROWTYPE;c live_answer_configurations%ROWTYPE;
BEGIN
 SELECT * INTO j FROM live_answer_jobs WHERE id=NEW.job_id;SELECT * INTO q FROM live_audience_events WHERE id=NEW.question_id;SELECT * INTO s FROM live_sessions WHERE id=j.session_id;SELECT * INTO c FROM live_answer_configurations WHERE session_id=s.id;
 IF NOT coalesce(dg_native_live_answer_valid(j.id,NULL,true) AND dg_native_live_answer_member(NEW.accepted_by,j.tenant_id,j.workspace_id) AND q.id=j.question_id AND q.status='queued' AND q.version=NEW.question_version AND s.status IN('live','preview') AND s.version=NEW.session_version AND(s.state::jsonb->>'epoch')::bigint=NEW.epoch AND s.state::jsonb->>'manual'='false' AND s.state::jsonb->>'interactionsPaused'='false' AND s.state::jsonb->>'answerId' IS NULL AND c.enabled=1 AND c.invalidated_at IS NULL AND c.generation=j.configuration_generation AND c.engine::jsonb=j.configuration::jsonb->'engine' AND NEW.input_hash=j.input_hash AND NEW.result_hash=j.result_hash,false) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Model adoption requires current explicit host approval and its immutable completed result';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_live_answer_origin_guard BEFORE INSERT ON live_answer_origins FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_origin_guard();
CREATE FUNCTION dg_native_live_answer_adoption_deferred() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF NOT dg_native_live_model_answer_valid(NEW.question_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Model adoption and the exact pending answer must commit together';END IF;RETURN NULL;END $dg$;
CREATE CONSTRAINT TRIGGER native_live_answer_adoption_atomic AFTER INSERT ON live_answer_origins DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_adoption_deferred();
CREATE FUNCTION dg_native_live_answer_event_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF NEW.answer_kind='local_model' AND OLD.answer IS NULL AND NOT EXISTS(SELECT 1 FROM live_answer_origins o JOIN live_answer_jobs j ON j.id=o.job_id WHERE o.question_id=NEW.id AND j.result::jsonb->>'answer'=NEW.answer AND NEW.prepared_epoch=o.epoch) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Model answers cannot bypass an immutable reviewed origin';END IF;RETURN NEW;END $dg$;
CREATE TRIGGER native_live_answer_event_guard BEFORE UPDATE ON live_audience_events FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_event_guard();
CREATE FUNCTION dg_native_live_answer_invalidate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN
 IF(NEW.withdrawn_at,NEW.invalidated_at) IS NOT DISTINCT FROM(OLD.withdrawn_at,OLD.invalidated_at) THEN RETURN NULL;END IF;
 UPDATE live_sessions s SET invalidated_at=dg_utc_now(),invalidation_reason='已采用模型答复的来源、用途或授权已变化，旧媒体不能继续采用。',version=version+1,updated_at=dg_utc_now() WHERE s.id=NEW.session_id AND s.invalidated_at IS NULL AND EXISTS(SELECT 1 FROM live_answer_origins o WHERE o.job_id=NEW.id AND(s.state::jsonb->>'answerId'=o.question_id OR EXISTS(SELECT 1 FROM live_segments p WHERE p.session_id=s.id AND p.segment::jsonb->>'answerId'=o.question_id) OR EXISTS(SELECT 1 FROM live_output_spans p JOIN live_outputs v ON v.id=p.output_id WHERE v.session_id=s.id AND p.frame::jsonb->>'answerId'=o.question_id)));
 UPDATE live_audience_events SET status='cancelled',version=version+1 WHERE id=NEW.question_id AND status='ready' AND EXISTS(SELECT 1 FROM live_answer_origins o WHERE o.job_id=NEW.id);RETURN NULL;
END $dg$;
CREATE TRIGGER native_live_answer_invalidate AFTER UPDATE ON live_answer_jobs FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_invalidate();
CREATE FUNCTION dg_native_live_answer_knowledge_invalidate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE field text:=CASE WHEN TG_TABLE_NAME='knowledge_documents' THEN 'documentId' ELSE 'collectionId' END;
BEGIN UPDATE live_answer_jobs j SET invalidated_at=dg_utc_now(),invalidation_reason='固定公开资料已修订、发布、撤回或收紧范围，原候选不再使用。',status=CASE WHEN status IN('queued','processing') THEN 'stale' ELSE status END,version=version+1,lease_token=NULL,lease_until=NULL,updated_at=dg_utc_now() WHERE j.invalidated_at IS NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(j.request::jsonb->'sources') s WHERE s->>field=NEW.id);RETURN NULL;END $dg$;
CREATE TRIGGER native_live_answer_document_invalidate AFTER UPDATE ON knowledge_documents FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_knowledge_invalidate();
CREATE TRIGGER native_live_answer_collection_invalidate AFTER UPDATE ON knowledge_collections FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_knowledge_invalidate();
CREATE FUNCTION dg_native_live_answer_member_invalidate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN
 UPDATE live_answer_jobs j SET invalidated_at=dg_utc_now(),invalidation_reason='模型准备、配置或主持确认人的授权已变化，请按当前权限重新准备。',status=CASE WHEN status IN('queued','processing') THEN 'stale' ELSE status END,version=version+1,lease_token=NULL,lease_until=NULL,updated_at=dg_utc_now() WHERE j.invalidated_at IS NULL AND(j.actor_id=OLD.user_id OR EXISTS(SELECT 1 FROM _dg_native_live_answer_config_versions c WHERE c.session_id=j.session_id AND c.generation=j.configuration_generation AND c.snapshot::jsonb->>'actorId'=OLD.user_id) OR EXISTS(SELECT 1 FROM live_answer_origins o WHERE o.job_id=j.id AND o.accepted_by=OLD.user_id)) AND(TG_OP='DELETE' OR NEW.tenant_id<>j.tenant_id OR NEW.role NOT IN('admin','editor') OR NOT(NEW.workspace_ids::jsonb ? j.workspace_id));
 UPDATE live_answer_configurations c SET invalidated_at=dg_utc_now(),invalidation_reason='原配置人的授权已变化，请明确重新配置。',version=version+1,updated_at=dg_utc_now() WHERE c.actor_id=OLD.user_id AND c.invalidated_at IS NULL AND(TG_OP='DELETE' OR NEW.tenant_id<>c.tenant_id OR NEW.role NOT IN('admin','editor') OR NOT(NEW.workspace_ids::jsonb ? c.workspace_id));RETURN NULL;
END $dg$;
CREATE TRIGGER native_live_answer_member_invalidate AFTER UPDATE OR DELETE ON memberships FOR EACH ROW EXECUTE FUNCTION dg_native_live_answer_member_invalidate();

-- Auto-candidate projection is restricted to one opt-in public scene and one already moderated question.
CREATE FUNCTION dg_native_live_answer_auto_context() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c live_answer_configurations%ROWTYPE;s live_sessions%ROWTYPE;q live_audience_events%ROWTYPE;selected_collection text;d record;product jsonb;sources jsonb:='[]'::jsonb;parts text[];part text;n integer:=0;i integer;total bigint;env text;
BEGIN
 SELECT app_env INTO env FROM _dg_native_runtime_control WHERE id=1;
 FOR c IN SELECT * FROM live_answer_configurations WHERE environment='mock' AND app_env=env AND enabled=1 AND auto_draft=1 AND invalidated_at IS NULL ORDER BY updated_at,session_id LOOP
  SELECT * INTO s FROM live_sessions WHERE id=c.session_id;IF s.status NOT IN('live','preview') OR s.invalidated_at IS NOT NULL OR s.state::jsonb->>'manual'<>'false' OR s.state::jsonb->>'interactionsPaused'<>'false' OR s.state::jsonb->>'answerId' IS NOT NULL OR s.snapshot::jsonb->'definition'->>'questionsEnabled'<>'true' OR NOT dg_native_live_answer_member(c.actor_id,s.tenant_id,s.workspace_id) OR NOT dg_native_live_scene_valid(s.id) OR(SELECT count(*) FROM live_answer_jobs WHERE session_id=s.id)>=100 OR(SELECT count(*) FROM live_answer_jobs WHERE session_id=s.id AND status IN('queued','processing'))>=3 THEN CONTINUE;END IF;
  SELECT * INTO q FROM live_audience_events a WHERE a.session_id=s.id AND a.kind='question' AND a.status='queued' AND NOT EXISTS(SELECT 1 FROM live_answer_jobs j WHERE j.question_id=a.id AND j.configuration_generation=c.generation) ORDER BY priority DESC,created_at,id LIMIT 1;IF FOUND THEN EXIT;END IF;
 END LOOP;IF q.id IS NULL THEN RETURN NULL;END IF;
 FOR selected_collection IN SELECT jsonb_array_elements_text(coalesce(s.snapshot::jsonb->'scene'->'app'->'collectionIds','[]'::jsonb)) LOOP
  FOR d IN SELECT v.*,k.id AS collection_id FROM knowledge_collections k JOIN knowledge_documents a ON a.collection_id=k.id JOIN knowledge_versions v ON v.id=a.published_version_id AND v.document_id=a.id WHERE k.id=selected_collection AND k.tenant_id=s.tenant_id AND k.workspace_id=s.workspace_id AND k.environment=s.environment AND k.app_env=s.app_env AND k.audience='public' AND k.scenes::jsonb ? 'live' AND a.tenant_id=s.tenant_id AND a.workspace_id=s.workspace_id AND v.status='published' ORDER BY a.id LOOP
   parts:=dg_native_live_answer_chunks(d.content);FOR i IN 1..cardinality(parts) LOOP sources:=sources||jsonb_build_array(jsonb_build_object('id','s'||n||'c'||(i-1),'kind','knowledge','title',d.title,'sourceLabel',d.source_label,'sourceUrl',d.source_url,'text',parts[i],'part',i-1,'collectionId',d.collection_id,'documentId',d.document_id,'versionId',d.id,'version',d.ordinal,'contentHash',d.content_hash));END LOOP;n:=n+1;
  END LOOP;
 END LOOP;
 FOR product IN SELECT value FROM jsonb_array_elements(s.snapshot::jsonb->'definition'->'products') WHERE value->>'expiresAt'>dg_utc_now() LOOP
  parts:=dg_native_live_answer_chunks('商品名称：'||(product->>'name')||CASE WHEN coalesce(product->>'priceLabel','')<>'' THEN E'\n资料标价：'||(product->>'priceLabel') ELSE '' END||E'\n说明：'||(product->>'description'));FOR i IN 1..cardinality(parts) LOOP sources:=sources||jsonb_build_array(jsonb_build_object('id','s'||n||'c'||(i-1),'kind','product','title',product->>'name','sourceLabel',product->>'sourceLabel','sourceUrl',product->'sourceUrl','text',parts[i],'part',i-1,'productId',product->>'id','expiresAt',product->>'expiresAt','productHash',encode(sha256(convert_to(dg_native_live_answer_canonical(product),'UTF8')),'hex')));END LOOP;n:=n+1;
 END LOOP;
 SELECT coalesce(sum(char_length(item->>'text')+(SELECT count(*) FROM regexp_split_to_table(item->>'text','') ch WHERE ascii(ch)>65535)),0) INTO total FROM jsonb_array_elements(sources) item;
 IF jsonb_array_length(sources) NOT BETWEEN 1 AND 512 OR total>180000 THEN UPDATE live_answer_configurations SET invalidated_at=dg_utc_now(),invalidation_reason='本场完整公开资料已无可用内容或超过512块/十八万字符，请调整来源后明确重新配置。',version=version+1,updated_at=dg_utc_now() WHERE session_id=c.session_id AND invalidated_at IS NULL;RETURN NULL;END IF;RETURN jsonb_build_object('session',to_jsonb(s),'question',to_jsonb(q),'configuration',to_jsonb(c),'sources',sources);
END $dg$;
CREATE FUNCTION dg_native_queue_live_answer_auto(target text,new_id text,input_text text,input_digest text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE s live_sessions%ROWTYPE;q live_audience_events%ROWTYPE;c live_answer_configurations%ROWTYPE;v jsonb:=input_text::jsonb;prior text;
BEGIN
 SELECT * INTO q FROM live_audience_events WHERE id=target;SELECT * INTO s FROM live_sessions WHERE id=q.session_id;SELECT * INTO c FROM live_answer_configurations WHERE session_id=s.id;
 IF NOT coalesce(q.status='queued' AND q.kind='question' AND s.status IN('live','preview') AND s.invalidated_at IS NULL AND s.state::jsonb->>'manual'='false' AND s.state::jsonb->>'interactionsPaused'='false' AND s.state::jsonb->>'answerId' IS NULL AND s.snapshot::jsonb->'definition'->>'questionsEnabled'='true' AND c.enabled=1 AND c.auto_draft=1 AND c.invalidated_at IS NULL AND dg_native_live_answer_member(c.actor_id,s.tenant_id,s.workspace_id) AND v->>'actorId'=c.actor_id AND v->>'sessionHash'=s.snapshot_hash AND(v->>'controllerVersion')::bigint=s.version AND(v->>'questionVersion')::bigint=q.version AND(v->>'configurationGeneration')::bigint=c.generation AND v->'configuration'=jsonb_build_object('engine',c.engine::jsonb,'language',c.language) AND v->'request'->>'question'=q.text AND input_digest=encode(sha256(convert_to(input_text,'UTF8')),'hex'),false) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Automatic candidates require explicit current configuration and a moderated public question';END IF;
 SELECT id INTO prior FROM live_answer_jobs WHERE question_id=q.id AND configuration_generation=c.generation AND controller_version=s.version AND question_version=q.version;IF prior IS NOT NULL THEN RETURN prior;END IF;
 IF(SELECT count(*) FROM live_answer_jobs WHERE session_id=s.id)>=100 OR(SELECT count(*) FROM live_answer_jobs WHERE session_id=s.id AND status IN('queued','processing'))>=3 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Automatic candidates retain the same history and pending limits';END IF;
 INSERT INTO live_answer_jobs(id,session_id,question_id,tenant_id,workspace_id,actor_id,environment,app_env,session_hash,request,configuration,controller_version,question_version,configuration_generation,input_hash,created_at,updated_at) VALUES(new_id,s.id,q.id,s.tenant_id,s.workspace_id,c.actor_id,s.environment,s.app_env,s.snapshot_hash,(v->'request')::text,(v->'configuration')::text,s.version,q.version,c.generation,input_digest,dg_utc_now(),dg_utc_now());INSERT INTO _dg_native_live_answer_inputs VALUES(new_id,input_text,input_digest,dg_utc_now());IF NOT dg_native_live_answer_source_valid(new_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Automatic candidate input must contain its exact fixed public sources';END IF;RETURN new_id;
END $dg$;
REVOKE ALL ON FUNCTION dg_native_live_answer_canonical(jsonb),dg_native_live_answer_chunks(text),dg_native_live_answer_member(text,text,text),dg_native_live_answer_source_valid(text),dg_native_live_answer_result_valid(text,text,text),dg_native_live_answer_valid(text,text,boolean),dg_native_live_answer_config_guard(),dg_native_live_answer_job_guard(),dg_native_live_answer_input_guard(),dg_native_live_answer_claim(),dg_native_live_answer_hold(text,text),dg_native_live_answer_renew(text,text,double precision),dg_native_live_answer_release(text,text),dg_native_live_answer_fail(text,text,text,text,boolean,boolean),dg_native_commit_live_answer(text,text,text,text,text,text),dg_native_live_model_answer_valid(text),dg_native_live_answer_origin_guard(),dg_native_live_answer_adoption_deferred(),dg_native_live_answer_event_guard(),dg_native_live_answer_invalidate(),dg_native_live_answer_knowledge_invalidate(),dg_native_live_answer_member_invalidate(),dg_native_live_answer_auto_context(),dg_native_queue_live_answer_auto(text,text,text,text) FROM PUBLIC;

-- Preserve all system-speech checks and also bind adopted model origins.
CREATE OR REPLACE FUNCTION dg_native_live_speech_valid(target text,expected_token text,completed boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j live_speech_jobs%ROWTYPE;p live_speech_plans%ROWTYPE;s live_sessions%ROWTYPE;v jsonb;q live_audience_events%ROWTYPE;
BEGIN
 SELECT * INTO j FROM live_speech_jobs WHERE id=target;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO p FROM live_speech_plans WHERE id=j.plan_id;SELECT * INTO s FROM live_sessions WHERE id=j.session_id;
 IF p.id IS NULL OR s.id IS NULL OR j.environment<>'mock' OR j.app_env<>(SELECT app_env FROM _dg_native_runtime_control WHERE id=1) OR j.invalidated_at IS NOT NULL OR j.withdrawn_at IS NOT NULL OR p.invalidated_at IS NOT NULL OR p.withdrawn_at IS NOT NULL OR p.status IN('cancelled','withdrawn') OR s.invalidated_at IS NOT NULL OR s.snapshot_hash<>p.session_hash OR NOT EXISTS(SELECT 1 FROM _dg_native_live_speech_job_inputs i WHERE i.job_id=j.id AND i.input_hash=j.input_hash) OR NOT EXISTS(SELECT 1 FROM _dg_native_live_speech_plan_inputs i WHERE i.plan_id=p.id AND i.input_hash=p.input_hash) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM memberships m WHERE m.user_id=j.actor_id AND m.tenant_id=j.tenant_id AND m.role='admin' AND m.workspace_ids::jsonb ? j.workspace_id) OR NOT EXISTS(SELECT 1 FROM memberships m WHERE m.user_id=p.actor_id AND m.tenant_id=p.tenant_id AND m.role='admin' AND m.workspace_ids::jsonb ? p.workspace_id) THEN RETURN false;END IF;
 v:=j.source::jsonb;
 IF v->>'kind'='cue' THEN IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.snapshot::jsonb->'definition'->'cues') c WHERE c->>'id'=v->>'cueId' AND c->>'kind'<>'video' AND c->>'text'=v->>'text' AND c->>'durationMs'=v->>'durationMs') THEN RETURN false;END IF;
 ELSE
  IF p.status<>'ready' OR p.result_hash IS NULL OR NOT EXISTS(SELECT 1 FROM _dg_native_live_speech_plan_outputs o WHERE o.plan_id=p.id AND o.result_hash=p.result_hash) THEN RETURN false;END IF;
  IF v->>'kind'='answer' THEN SELECT * INTO q FROM live_audience_events WHERE id=v->>'questionId';IF NOT FOUND OR q.session_id<>s.id OR q.answer IS DISTINCT FROM v->>'text' OR q.citations::jsonb IS DISTINCT FROM v->'citations' OR(q.answer_kind='knowledge' AND NOT dg_native_live_knowledge_answer_valid(q.id) OR q.answer_kind='local_model' AND NOT dg_native_live_model_answer_valid(q.id)) THEN RETURN false;END IF;END IF;
 END IF;
 IF completed THEN RETURN j.status='succeeded' AND EXISTS(SELECT 1 FROM _dg_native_live_speech_outputs o WHERE o.job_id=j.id);END IF;
 IF j.status<>'processing' OR j.lease_token IS DISTINCT FROM expected_token OR j.lease_until<=dg_utc_now() OR NOT EXISTS(SELECT 1 FROM _dg_native_live_speech_leases l WHERE l.job_id=j.id AND l.token=expected_token AND l.lease_until>dg_utc_now()) THEN RETURN false;END IF;
 IF v->>'kind'='cue' THEN RETURN s.status IN('ready','scheduled') AND p.result_hash IS NULL;END IF;
 IF s.status NOT IN('live','preview') OR(s.state::jsonb->>'epoch')::bigint<>(v->>'epoch')::bigint OR NOT EXISTS(SELECT 1 FROM live_outputs o WHERE o.session_id=s.id AND o.snapshot::jsonb->'settings'->>'speechPlanId'=p.id AND o.invalidated_at IS NULL AND o.withdrawn_at IS NULL) THEN RETURN false;END IF;
 IF v->>'kind'='manual' THEN RETURN(s.state::jsonb->>'manual')::boolean AND s.state::jsonb->>'surface'='manual';END IF;
 RETURN q.status='ready' AND q.version=(v->>'questionVersion')::bigint AND q.prepared_epoch=(v->>'epoch')::bigint AND NOT(s.state::jsonb->>'manual')::boolean AND NOT(s.state::jsonb->>'interactionsPaused')::boolean AND s.state::jsonb->>'answerId' IS NULL;
EXCEPTION WHEN data_exception THEN RETURN false;
END $dg$;

